const seedlingOverflow = (trayCount, reservedTrays, vanCount, chilledTransport) => {
  const shippableTrays = Math.max(trayCount - reservedTrays, 0);
  const baseCapacity = vanCount * 24;
  const chillBuffer = chilledTransport ? vanCount * 3 : 0;
  const dispatchCapacity = Math.max(baseCapacity - chillBuffer, 0);
  return BigInt(Math.max(shippableTrays - dispatchCapacity, 0));
};
export async function loadParley() { return { seedling_overflow: seedlingOverflow }; }

