use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub full_price_guests: i64,
    pub concession_guests: i64,
    pub prepaid_credit_cents: i64,
    pub weekend_event: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        if self.full_price_guests < 0
            || self.concession_guests < 0
            || self.prepaid_credit_cents < 0
        {
            return false;
        }

        let full = self.full_price_guests.checked_mul(1800);
        let concession = self.concession_guests.checked_mul(950);
        let fee = if self.weekend_event {
            self.full_price_guests
                .checked_add(self.concession_guests)
                .and_then(|guests| guests.checked_mul(175))
        } else {
            Some(0)
        };

        match (full, concession, fee) {
            (Some(full), Some(concession), Some(fee)) => full
                .checked_add(concession)
                .and_then(|base| base.checked_add(fee))
                .is_some(),
            _ => false,
        }
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub full_price_charge_cents: i64,
    pub concession_charge_cents: i64,
    pub weekend_fee_cents: i64,
    pub gross_charge_cents: i64,
    pub credit_used_cents: i64,
    pub amount_due_cents: i64,
    pub payment_state: String,
}

pub fn event_amount_due(f: i64, c: i64, credit: i64, weekend: bool) -> i64 {
    let full = f * 1800;
    let concession = c * 950;
    let fee = if weekend { (f + c) * 175 } else { 0 };
    let gross = full + concession + fee;
    gross.saturating_sub(credit)
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let full = v.full_price_guests * 1800;
    let concession = v.concession_guests * 950;
    let fee = if v.weekend_event {
        (v.full_price_guests + v.concession_guests) * 175
    } else {
        0
    };
    let gross = full + concession + fee;
    let due = event_amount_due(
        v.full_price_guests,
        v.concession_guests,
        v.prepaid_credit_cents,
