const clinicQueuePressure = (scheduledCount, walkInCount, clinicianCount, urgentOpen) => {
  const patientTotal = scheduledCount + walkInCount;
  const urgentSlots = urgentOpen ? clinicianCount * 2 : 0;
  const serviceSlots = clinicianCount * 8 + urgentSlots;
  const overflowCount = Math.max(patientTotal - serviceSlots, 0);
  const waitingGroups = Math.ceil(overflowCount / 5);
  return overflowCount * 4 + waitingGroups * 3;
};
export async function loadParley() { return { clinic_queue_pressure: clinicQueuePressure }; }

