const festivalPowerScore = (speakerTowers, wattsEach, lightRigs, weatherCover) => {
  const speakerWatts = speakerTowers * wattsEach;
  const lightingWatts = lightRigs * 900;
  const weatherWatts = weatherCover ? (speakerTowers + lightRigs) * 75 : 0;
  const connectionPoints = speakerTowers * 3 + lightRigs * 5;
  return speakerWatts + lightingWatts + weatherWatts + connectionPoints * 20;
};
export async function loadParley() { return { festival_power_score: festivalPowerScore }; }

