export type RequestInput={scheduled_count:number;walk_in_count:number;clinician_count:number;urgent_open:boolean};
export const clinicQueuePressure=(scheduled:number,walkIns:number,clinicians:number,urgentOpen:boolean)=>{
  const patientTotal=scheduled+walkIns;
  const urgentSlots=urgentOpen?clinicians*2:0;
  const serviceSlots=clinicians*8+urgentSlots;
  const overflowCount=Math.max(patientTotal-serviceSlots,0);
  const waitingGroups=Math.ceil(overflowCount/5);
  return overflowCount*4+waitingGroups*3;
};
export const handle=(v:RequestInput)=>{const total=v.scheduled_count+v.walk_in_count,urgent=v.urgent_open?v.clinician_count*2:0,slots=v.clinician_count*8+urgent,overflow=Math.max(total-slots,0),groups=Math.ceil(overflow/5);return {patient_total:total,urgent_slots:urgent,service_slots:slots,overflow_count:overflow,waiting_groups:groups,queue_pressure:clinicQueuePressure(v.scheduled_count,v.walk_in_count,v.clinician_count,v.urgent_open),queue_state:overflow===0?"clear":v.urgent_open?"urgent":"delayed"};};
export async function loadParley(){return {clinic_queue_pressure:(s:number,w:number,c:number,u:boolean)=>BigInt(clinicQueuePressure(s,w,c,u))};}

