pub fn clinic_queue_pressure(s:i64,w:i64,c:i64,u:bool)->i64{
    let patient_total=s+w;
    let urgent_slots=if u{c*2}else{0};
    let service_slots=c*8+urgent_slots;
    let overflow_count=(patient_total-service_slots).max(0);
